* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background: #f4f6f9;
  color: #333;
}

h1 {
  text-align: center;
  padding: 18px 0 6px;
  font-size: 1.6rem;
  color: #2c3e50;
}

.container {
  display: flex;
  gap: 24px;
  padding: 12px 24px 24px;
  max-width: 1600px;
  margin: 0 auto;
  align-items: flex-start;
}

/* ---------- Bubble chart panel ---------- */
.chart-panel {
  flex: 1 1 55%;
  min-width: 0;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,.1);
  padding: 16px;
}

.chart-panel h2 {
  font-size: 1.05rem;
  margin-bottom: 8px;
  color: #34495e;
}

#bubble-chart {
  width: 100%;
  position: relative;
}

#bubble-chart svg {
  display: block;
}

/* Bubble styling */
.bubble {
  cursor: pointer;
  stroke: #fff;
  stroke-width: 1.5;
  transition: opacity .15s;
}

.bubble.dimmed {
  opacity: .3;
}

.bubble.selected {
  stroke: #222;
  stroke-width: 3;
}

.bubble-label {
  pointer-events: none;
  font-size: 10px;
  font-weight: 600;
  fill: #fff;
  text-anchor: middle;
  dominant-baseline: central;
}

/* Legend */
.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  margin-top: 10px;
  padding: 6px 0;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: .78rem;
  color: #555;
}

.legend-swatch {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  flex-shrink: 0;
}

/* ---------- Table panel ---------- */
.table-panel {
  flex: 1 1 45%;
  min-width: 0;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,.1);
  padding: 16px;
  max-height: 720px;
  overflow-y: auto;
}

.table-panel h2 {
  font-size: 1.05rem;
  margin-bottom: 8px;
  color: #34495e;
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: .85rem;
}

#stock-table thead th {
  position: sticky;
  top: 0;
  background: #34495e;
  color: #fff;
  padding: 8px 10px;
  text-align: left;
  font-weight: 600;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
}

#stock-table thead th:hover {
  background: #2c3e50;
}

#stock-table tbody tr {
  cursor: pointer;
  transition: background .12s;
}

#stock-table tbody tr:nth-child(even) {
  background: #f9fafc;
}

#stock-table tbody tr:hover {
  background: #eaf0fb;
}

#stock-table tbody tr.highlighted {
  background: #d5e8ff !important;
  font-weight: 600;
}

#stock-table td {
  padding: 7px 10px;
  border-bottom: 1px solid #e8eaed;
  white-space: nowrap;
}

/* ---------- Tooltip ---------- */
.tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(44, 62, 80, .92);
  color: #fff;
  padding: 9px 13px;
  border-radius: 5px;
  font-size: .82rem;
  line-height: 1.45;
  max-width: 260px;
  box-shadow: 0 3px 10px rgba(0,0,0,.25);
  opacity: 0;
  transition: opacity .15s;
  z-index: 100;
}

.tooltip.visible {
  opacity: 1;
}

.tooltip .tt-ticker {
  font-weight: 700;
  font-size: .92rem;
}

.tooltip .tt-name {
  margin-top: 2px;
}

.tooltip .tt-sector {
  margin-top: 3px;
  color: #a0cfff;
}

