(function () {
  "use strict";

  /* ================================================================
     1. LOAD DATA
     ================================================================ */
  d3.csv("data/stock-descriptions.csv").then(function (raw) {
    var data = raw.map(function (d) {
      return {
        ticker: d.ticker,
        name: d["full name"],
        sector: d.sector,
        marketCap: d.marketCap ? +d.marketCap : null,
        country: d.country || null,
        website: d.website || null,
      };
    });

    buildBubbleChart(data);
    buildTable(data);
  });

  /* ================================================================
     2. SHARED STATE
     ================================================================ */
  var selectedTicker = null;
  var onSelect = []; // callbacks: fn(ticker|null)

  function selectStock(ticker) {
    selectedTicker = selectedTicker === ticker ? null : ticker;
    onSelect.forEach(function (fn) {
      fn(selectedTicker);
    });
  }

  /* ================================================================
     3. BUBBLE CHART
     ================================================================ */
  function buildBubbleChart(data) {
    var container = d3.select("#bubble-chart");
    var width = 700;
    var height = 560;

    /* --- Colour scale by sector --- */
    var sectors = Array.from(new Set(data.map(function (d) { return d.sector; })));
    var palette = [
      "#4e79a7", "#f28e2b", "#e15759", "#76b7b2",
      "#59a14f", "#edc948", "#b07aa1", "#ff9da7",
      "#9c755f", "#bab0ac"
    ];
    var colorScale = d3.scaleOrdinal().domain(sectors).range(palette);

    /* --- Size scale (sqrt so area ~ marketCap) --- */
    var capsOnly = data.filter(function (d) { return d.marketCap !== null; });
    var capExtent = d3.extent(capsOnly, function (d) { return d.marketCap; });
    var radiusScale = d3.scaleSqrt().domain([0, capExtent[1]]).range([6, 52]);
    var etfRadius = 14; // uniform size for ETFs

    function radius(d) {
      return d.marketCap !== null ? radiusScale(d.marketCap) : etfRadius;
    }

    /* --- Sector center positions (spread evenly) --- */
    var sectorCenters = {};
    var cols = Math.ceil(Math.sqrt(sectors.length));
    var rows = Math.ceil(sectors.length / cols);
    sectors.forEach(function (s, i) {
      var col = i % cols;
      var row = Math.floor(i / cols);
      sectorCenters[s] = {
        x: (col + 0.5) / cols * width,
        y: (row + 0.5) / rows * height,
      };
    });

    /* --- SVG --- */
    var svg = container
      .append("svg")
      .attr("viewBox", "0 0 " + width + " " + height)
      .attr("preserveAspectRatio", "xMidYMid meet")
      .style("width", "100%")
      .style("height", "auto");

    /* --- Tooltip --- */
    var tooltip = d3
      .select("body")
      .append("div")
      .attr("class", "tooltip");

    /* --- Force simulation --- */
    var nodes = data.map(function (d) {
      return Object.assign({}, d, {
        r: radius(d),
        x: sectorCenters[d.sector].x + (Math.random() - 0.5) * 40,
        y: sectorCenters[d.sector].y + (Math.random() - 0.5) * 40,
      });
    });

    var simulation = d3
      .forceSimulation(nodes)
      .force("x", d3.forceX(function (d) { return sectorCenters[d.sector].x; }).strength(0.35))
      .force("y", d3.forceY(function (d) { return sectorCenters[d.sector].y; }).strength(0.35))
      .force("collide", d3.forceCollide(function (d) { return d.r + 2; }).iterations(4))
      .force("center", d3.forceCenter(width / 2, height / 2).strength(0.05))
      .alphaDecay(0.02)
      .on("tick", ticked);

    /* --- Draw bubbles --- */
    var bubbleG = svg
      .selectAll(".bubble-g")
      .data(nodes)
      .join("g")
      .attr("class", "bubble-g");

    var circles = bubbleG
      .append("circle")
      .attr("class", "bubble")
      .attr("r", function (d) { return d.r; })
      .attr("fill", function (d) { return colorScale(d.sector); })
      .on("mouseover", function (event, d) {
        if (d.sector === "ETF") return;
        tooltip
          .html(
            '<div class="tt-ticker">' + d.ticker + '</div>' +
            '<div class="tt-name">' + d.name + '</div>' +
            '<div class="tt-sector">' + d.sector + '</div>'
          )
          .classed("visible", true);
      })
      .on("mousemove", function (event) {
        tooltip
          .style("left", event.pageX + 14 + "px")
          .style("top", event.pageY - 28 + "px");
      })
      .on("mouseout", function () {
        tooltip.classed("visible", false);
      })
      .on("click", function (event, d) {
        selectStock(d.ticker);
      });

    /* --- Labels inside bubbles --- */
    bubbleG
      .append("text")
      .attr("class", "bubble-label")
      .text(function (d) { return d.ticker; })
      .style("font-size", function (d) {
        return Math.max(7, Math.min(d.r * 0.55, 14)) + "px";
      });

    function ticked() {
      /* Keep bubbles inside the SVG viewport */
      nodes.forEach(function (d) {
        d.x = Math.max(d.r, Math.min(width - d.r, d.x));
        d.y = Math.max(d.r, Math.min(height - d.r, d.y));
      });

      bubbleG.attr("transform", function (d) {
        return "translate(" + d.x + "," + d.y + ")";
      });
    }

    /* --- Selection highlight --- */
    onSelect.push(function (ticker) {
      circles
        .classed("selected", function (d) { return d.ticker === ticker; })
        .classed("dimmed", function (d) { return ticker !== null && d.ticker !== ticker; });
    });

    /* --- Legend --- */
    var legend = container.append("div").attr("class", "legend");
    sectors.forEach(function (s) {
      var item = legend.append("div").attr("class", "legend-item");
      item
        .append("span")
        .attr("class", "legend-swatch")
        .style("background", colorScale(s));
      item.append("span").text(s);
    });
  }

  /* ================================================================
     4. DATA TABLE
     ================================================================ */
  function buildTable(data) {
    var tableEl = d3.select("#stock-table");

    /* --- Header --- */
    var thead = tableEl.append("thead").append("tr");
    var columns = [
      { key: "ticker", label: "Ticker" },
      { key: "name", label: "Full Company Name" },
      { key: "sector", label: "Sector" },
      { key: "marketCap", label: "Market Cap" },
    ];

    var sortKey = null;
    var sortAsc = true;

    thead
      .selectAll("th")
      .data(columns)
      .join("th")
      .text(function (d) { return d.label; })
      .on("click", function (event, col) {
        if (sortKey === col.key) {
          sortAsc = !sortAsc;
        } else {
          sortKey = col.key;
          sortAsc = true;
        }
        renderRows();
      });

    /* --- Body --- */
    var tbody = tableEl.append("tbody");

    function formatCap(v) {
      if (v == null) return "N/A";
      if (v >= 1e12) return (v / 1e12).toFixed(2) + "T";
      if (v >= 1e9) return (v / 1e9).toFixed(2) + "B";
      if (v >= 1e6) return (v / 1e6).toFixed(2) + "M";
      return v.toLocaleString();
    }

    function renderRows() {
      var sorted = data.slice();
      if (sortKey) {
        sorted.sort(function (a, b) {
          var va = a[sortKey];
          var vb = b[sortKey];
          if (va == null) return 1;
          if (vb == null) return -1;
          if (typeof va === "string") {
            return sortAsc
              ? va.localeCompare(vb)
              : vb.localeCompare(va);
          }
          return sortAsc ? va - vb : vb - va;
        });
      }

      var rows = tbody
        .selectAll("tr")
        .data(sorted, function (d) { return d.ticker; });

      rows.exit().remove();

      var enter = rows.enter().append("tr");
      enter.append("td");
      enter.append("td");
      enter.append("td");
      enter.append("td");

      var merged = enter.merge(rows);
      merged.attr("data-ticker", function (d) { return d.ticker; });

      merged
        .select("td:nth-child(1)")
        .text(function (d) { return d.ticker; });
      merged
        .select("td:nth-child(2)")
        .text(function (d) { return d.name; });
      merged
        .select("td:nth-child(3)")
        .text(function (d) { return d.sector; });
      merged
        .select("td:nth-child(4)")
        .text(function (d) { return formatCap(d.marketCap); });

      merged.on("click", function (event, d) {
        selectStock(d.ticker);
      });

      merged.order();

      // reapply highlights
      updateHighlight(selectedTicker);
    }

    function updateHighlight(ticker) {
      tbody
        .selectAll("tr")
        .classed("highlighted", function (d) { return d.ticker === ticker; });

      // scroll highlighted row into view
      if (ticker) {
        var row = tbody
          .selectAll("tr")
          .filter(function (d) { return d.ticker === ticker; })
          .node();
        if (row) {
          row.scrollIntoView({ block: "nearest", behavior: "smooth" });
        }
      }
    }

    onSelect.push(updateHighlight);

    renderRows();
  }
})();

