    var thead = tableEl.append("thead").append("tr");
    var columns = [
      { key: "ticker", label: "Ticker" },
      { key: "name", label: "Full Company Name" },
      { key: "sector", label: "Sector" },
      { key: "marketCap", label: "Market Cap" },
    ];

    var sortKey = null;
    var sortAsc = true;

    thead
      .selectAll("th")
      .data(columns)
      .join("th")
      .text(function (d) { return d.label; })
      .on("click", function (event, col) {
        if (sortKey === col.key) {
          sortAsc = !sortAsc;
        } else {
          sortKey = col.key;
          sortAsc = true;
        }
        renderRows();
      });

    /* --- Body --- */
    var tbody = tableEl.append("tbody");

    function formatCap(v) {
      if (v == null) return "N/A";
      if (v >= 1e12) return (v / 1e12).toFixed(2) + "T";
      if (v >= 1e9) return (v / 1e9).toFixed(2) + "B";
      if (v >= 1e6) return (v / 1e6).toFixed(2) + "M";
      return v.toLocaleString();
    }

    function renderRows() {
      var sorted = data.slice();
      if (sortKey) {
        sorted.sort(function (a, b) {
          var va = a[sortKey];
          var vb = b[sortKey];
          if (va == null) return 1;
          if (vb == null) return -1;
          if (typeof va === "string") {
            return sortAsc
              ? va.localeCompare(vb)
              : vb.localeCompare(va);
          }
          return sortAsc ? va - vb : vb - va;
        });
      }

      var rows = tbody
        .selectAll("tr")
        .data(sorted, function (d) { return d.ticker; });

      rows.exit().remove();

      var enter = rows.enter().append("tr");
      enter.append("td");
      enter.append("td");
      enter.append("td");
      enter.append("td");

      var merged = enter.merge(rows);
      merged.attr("data-ticker", function (d) { return d.ticker; });

      merged
        .select("td:nth-child(1)")
        .text(function (d) { return d.ticker; });
      merged
        .select("td:nth-child(2)")
        .text(function (d) { return d.name; });
      merged
        .select("td:nth-child(3)")
        .text(function (d) { return d.sector; });
      merged
        .select("td:nth-child(4)")
        .text(function (d) { return formatCap(d.marketCap); });

      merged.on("click", function (event, d) {
        selectStock(d.ticker);
      });

      merged.order();

      // reapply highlights
      updateHighlight(selectedTicker);
    }

    function updateHighlight(ticker) {
      tbody
        .selectAll("tr")
        .classed("highlighted", function (d) { return d.ticker === ticker; });

      // scroll highlighted row into view
      if (ticker) {
        var row = tbody
          .selectAll("tr")
          .filter(function (d) { return d.ticker === ticker; })
          .node();
        if (row) {
          row.scrollIntoView({ block: "nearest", behavior: "smooth" });
        }
      }
    }

    onSelect.push(updateHighlight);

    renderRows();
  }
})();
